        SELECT
        CONCAT(#{occrClsfCd} || #{tskClsfCd}, LPAD(NVL(MAX(TO_NUMBER(SUBSTR(MSG_ID, 6))) + 1, 1), 5, '0')) AS MSG_ID
        FROM CLOVER_MSG_MNG
        WHERE OCCR_CLSF_CD = #{occrClsfCd}
        AND TSK_CLSF_CD = #{tskClsfCd}

    INSERT INTO CLOVER_MSG_MNG (
              MSG_ID
            , MSG_CLSF
            , TSK_CLSF_CD
            , OCCR_CLSF_CD
            , MSG_PRNT_CD
            , MSG_CN
            , USE_YN
            , REG_DTTM
            , REGR_ID
            , CHGR_ID
    ) VALUES (
              #{msgId}
            , #{msgClsf}
            , #{tskClsfCd}
            , #{occrClsfCd}
            , #{msgPrntCd}
            , #{msgCn}
            , 'Y'
            , SYSDATE
            , #{regrId}
            , #{chgrId}
    )

